                ReturnValues='ALL_NEW'
            )

            return self._dynamodb_to_python_obj(response['Attributes'])
        except self.dynamodb.meta.client.exceptions.ConditionalCheckFailedException:
            raise ValueError(f"Booking {booking_id} not found")
