            continue
        dir_path = workspace / "output" / code_uri
        if not dir_path.is_dir():
            findings.append(
                _finding("C1", "ERROR", f"{logical_name}.CodeUri '{code_uri}' does not exist on disk.", logical_name)
            )
    return findings


