RESPONSE = '''"""HTTP response helpers shared by this function's returns.

Global middleware contract (analysis_report.global_middleware[0], D-10): the
monolith's flask-cors CORS(app) puts Access-Control-Allow-Origin on EVERY
response (echoing the request Origin, '*' when there is none) and Vary: Origin
when it echoes; Access-Control-Allow-Methods / Access-Control-Allow-Headers
appear only on preflight OPTIONS. With proxy integration the function must do
this itself on every return, errors included.

Error exit (D-11): a faithful port of app.py:28-36 @app.errorhandler(Exception)
-- ValueError -> 400 {"error", "type"}, any other exception -> 500 {"error",
"type"} with str(e) kept verbatim.
"""
import json

ALLOW_ORIGIN = "Access-Control-Allow-Origin"
VARY = "Vary"
ALLOW_METHODS = "Access-Control-Allow-Methods"
ALLOW_HEADERS = "Access-Control-Allow-Headers"
ALLOW_METHODS_VALUE = "DELETE, GET, HEAD, OPTIONS, PATCH, POST, PUT"


def request_header(event, name):
    headers = event.get("headers") or {}
    for key, value in headers.items():
        if isinstance(key, str) and key.lower() == name.lower():
            if isinstance(value, list):
                return value[0] if value else None
            return value
    return None


def json_response(status_code, payload, event, content_type="application/json"):
    headers = {"Content-Type": content_type}
    origin = request_header(event, "origin")
    if origin:
        headers[ALLOW_ORIGIN] = origin
        headers[VARY] = "Origin"
    else:
        headers[ALLOW_ORIGIN] = "*"
    if (event.get("httpMethod") or "").upper() == "OPTIONS":
        # Preflight is answered by the gateway's Cors block in the target
        # (D-9); this branch only keeps a direct OPTIONS invocation
        # equivalent to flask-cors' preflight response.
        headers[ALLOW_METHODS] = ALLOW_METHODS_VALUE
        requested = request_header(event, "access-control-request-headers")
        headers[ALLOW_HEADERS] = requested if requested else "Content-Type, Authorization"
    return {"statusCode": status_code, "headers": headers, "body": json.dumps(payload)}


def error_response(exc, event):
    if isinstance(exc, ValueError):
        return json_response(400, {"error": str(exc), "type": "ValueError"}, event)
    return json_response(500, {"error": str(exc), "type": type(exc).__name__}, event)


def handle_errors(func):
    """Route-level handler: everything not answered by an explicit branch
    falls into the monolith's global error shape."""
    def wrapped(event, context):
        try:
            return func(event, context)
        except Exception as exc:  # noqa: BLE001 - mirrors @app.errorhandler(Exception)
            return error_response(exc, event)
    wrapped.__name__ = getattr(func, "__name__", "lambda_handler")
    return wrapped
'''

