(SI-10, D-13). Read paths keep the monolith's exact semantics: scans are
single-page with no LastEvaluatedKey handling (SI-4), swallowed read failures
degrade exactly where the monolith degraded (D-14), and Decimal values are
converted back to int/float (storage.py:44-53).
"""
import uuid
from datetime import datetime
from decimal import Decimal

from boto3.dynamodb.conditions import Attr


def to_python_obj(obj):
    """Decimal -> int when whole else float, recursively (storage.py:44-53)."""
    if isinstance(obj, Decimal):
        if obj % 1 == 0:
            return int(obj)
        return float(obj)
    if isinstance(obj, dict):
        return {key: to_python_obj(value) for key, value in obj.items()}
    if isinstance(obj, list):
        return [to_python_obj(item) for item in obj]
    return obj


def to_dynamodb_obj(obj):
    """float -> Decimal(str) recursively (storage.py:35-41)."""
    if isinstance(obj, float):
        return Decimal(str(obj))
    if isinstance(obj, dict):
        return {key: to_dynamodb_obj(value) for key, value in obj.items()}
    if isinstance(obj, list):
        return [to_dynamodb_obj(item) for item in obj]
    return obj


# ---- flight catalog -------------------------------------------------------

def get_flight(dynamodb, table_name, flight_id):
    try:
        response = dynamodb.Table(table_name).get_item(Key={'id': flight_id})
        if 'Item' in response:
            return to_python_obj(response['Item'])
        return None
    except Exception as exc:
        print(f"Error getting flight {flight_id}: {str(exc)}")
        return None


def search_flights(dynamodb, table_name, departure_code, arrival_code, departure_date):
    try:
        response = dynamodb.Table(table_name).scan(
            FilterExpression=Attr('departureAirportCode').eq(departure_code)
            & Attr('arrivalAirportCode').eq(arrival_code)
            & Attr('departureDate').eq(departure_date))
        return [to_python_obj(item) for item in response.get('Items', [])]
    except Exception as exc:
        print(f"Error searching flights: {str(exc)}")
        return []


def reserve_flight_seat(dynamodb, table_name, flight_id):
    table = dynamodb.Table(table_name)
    client = dynamodb.meta.client
    try:
        table.update_item(
            Key={'id': flight_id},
            UpdateExpression='SET seatCapacity = seatCapacity - :dec',
            ConditionExpression='seatCapacity > :zero AND attribute_exists(id)',
            ExpressionAttributeValues={':dec': 1, ':zero': 0},
            ReturnValues='UPDATED_NEW')
        return True
    except client.exceptions.ConditionalCheckFailedException:
        raise ValueError(f"Flight {flight_id} is fully booked or does not exist")
    except Exception as exc:
        raise ValueError(f"Failed to reserve seat: {str(exc)}")


def release_flight_seat(dynamodb, table_name, flight_id):
    table = dynamodb.Table(table_name)
    client = dynamodb.meta.client
    try:
        # GAP-18 kept as-is: read the cap first, then a conditional increment.
        flight = get_flight(dynamodb, table_name, flight_id)
        if not flight:
            raise ValueError(f"Flight {flight_id} does not exist")
        table.update_item(
            Key={'id': flight_id},
            UpdateExpression='SET seatCapacity = seatCapacity + :inc',
            ConditionExpression='seatCapacity < :max',
            ExpressionAttributeValues={':inc': 1, ':max': flight['maximumSeating']},
            ReturnValues='UPDATED_NEW')
        return True
    except client.exceptions.ConditionalCheckFailedException:
        raise ValueError("Cannot release seat, already at maximum capacity")
    except Exception as exc:
        raise ValueError(f"Failed to release seat: {str(exc)}")


# ---- bookings -------------------------------------------------------------

def create_booking(dynamodb, table_name, booking_data):
    booking_id = str(uuid.uuid4())
    booking = {
        'id': booking_id,
        'bookingOutboundFlightId': booking_data['outboundFlightId'],
        'checkedIn': False,
        'customer': booking_data['customerId'],
        'paymentToken': booking_data['chargeId'],
        'status': 'UNCONFIRMED',
        'createdAt': datetime.now().isoformat(),
        'bookingReference': None,
    }
    try:
        dynamodb.Table(table_name).put_item(Item=to_dynamodb_obj(booking))
        return to_python_obj(booking)
    except Exception as exc:
        raise ValueError(f"Failed to create booking: {str(exc)}")


def get_booking(dynamodb, table_name, booking_id):
    try:
        response = dynamodb.Table(table_name).get_item(Key={'id': booking_id})
        if 'Item' in response:
            return to_python_obj(response['Item'])
        return None
    except Exception as exc:
        print(f"Error getting booking {booking_id}: {str(exc)}")
        return None


def update_booking_status(dynamodb, table_name, booking_id, status, booking_reference=None):
    table = dynamodb.Table(table_name)
    client = dynamodb.meta.client
    try:
        update_expr = 'SET #status = :status'
        expr_attr_names = {'#status': 'status'}
        expr_attr_values = {':status': status}
        if booking_reference:
            update_expr += ', bookingReference = :ref'
            expr_attr_values[':ref'] = booking_reference
        response = table.update_item(
            Key={'id': booking_id},
            UpdateExpression=update_expr,
            ExpressionAttributeNames=expr_attr_names,
            ExpressionAttributeValues=expr_attr_values,
            ConditionExpression='attribute_exists(id)',
            ReturnValues='ALL_NEW')
        return to_python_obj(response['Attributes'])
    except client.exceptions.ConditionalCheckFailedException:
        raise ValueError(f"Booking {booking_id} not found")
    except Exception as exc:
        raise ValueError(f"Failed to update booking: {str(exc)}")


def bookings_by_customer(dynamodb, table_name, customer_id, status=None):
    try:
        filter_expr = Attr('customer').eq(customer_id)
        if status:
            filter_expr = filter_expr & Attr('status').eq(status)
        response = dynamodb.Table(table_name).scan(FilterExpression=filter_expr)
        return [to_python_obj(item) for item in response.get('Items', [])]
    except Exception as exc:
        print(f"Error getting bookings for customer {customer_id}: {str(exc)}")
        return []


# ---- loyalty --------------------------------------------------------------

def add_loyalty_entry(dynamodb, table_name, customer_id, points):
    loyalty_entry = {
        'id': str(uuid.uuid4()),
        'customerId': customer_id,
        'points': points,
        'flag': 'active',
        'date': datetime.now().isoformat(),
    }
    try:
        dynamodb.Table(table_name).put_item(Item=to_dynamodb_obj(loyalty_entry))
        return to_python_obj(loyalty_entry)
    except Exception as exc:
        raise ValueError(f"Failed to add loyalty points: {str(exc)}")


def loyalty_points_total(dynamodb, table_name, customer_id):
    try:
        response = dynamodb.Table(table_name).scan(
            FilterExpression=Attr('customerId').eq(customer_id) & Attr('flag').eq('active'))
        total = 0
        for item in response.get('Items', []):
            points = item.get('points', 0)
            total += int(points)
        return total
    except Exception as exc:
        print(f"Error getting loyalty points for {customer_id}: {str(exc)}")
        return 0


